import json
TOOLS = {"get_leave_days": lambda emp_id: {"emp_id": emp_id, "left": 7}}
model_out = '{"tool": "get_leave_days", "args": {"emp_id": "E102"}}'
call = json.loads(model_out)
if call["tool"] not in TOOLS:
    raise ValueError("unknown tool")
result = TOOLS[call["tool"]](**call["args"])
print("tool result ->", json.dumps(result, ensure_ascii=False))
# tool result -> {"emp_id": "E102", "left": 7}

gold = {"q1": "doc7", "q2": "doc2", "q3": "doc9"}
ranked = {"q1": ["doc7", "doc1", "doc3"], "q2": ["doc5", "doc2", "doc8"], "q3": ["doc4", "doc6", "doc1"]}
def recall_at(k):
    return sum(gold[q] in ranked[q][:k] for q in gold) / len(gold)
mrr = sum((1 / (ranked[q].index(gold[q]) + 1)) if gold[q] in ranked[q] else 0 for q in gold) / len(gold)
print("recall@1", round(recall_at(1), 2), "recall@3", round(recall_at(3), 2), "MRR", round(mrr, 2))
# recall@1 0.33 recall@3 0.67 MRR 0.5
